const axios = require('axios');

async function getVideoInfo(link) {
  const url = `https://download.vgasoft.vn/web/c/tiktok/getVideo?link=${encodeURIComponent(link)}`;
  const headers = {
    'OS': 'webSite',
    'PUBLIC_API_TOKEN': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJQVUJMSUNfQVBJX1RPS0VOIjoicGRtc1NEIzc4OUAxMyIsImlhdCI6MTc4NjQ2MjM2MiwiZXhwIjoxNzg2NDYyNDAyfQ._dEjHDTn9y5F1QqQQ_YI12KK0f4I8n-oFLqCM4_ZVog'
  };

  try {
    const response = await axios.get(url, { headers });
    const data = response.data;

    if (data.success && data.result && data.result.length > 0) {
      const videoData = data.result[0];
      const videoInfo = `
Nickname: ${videoData.author.nickname}
Video ID: ${videoData.video.id}
Video URL: ${videoData.video.url}
Cover Image: ${videoData.video.cover}
      `;
      return videoInfo;
    } else {
      return 'Gagal mendapatkan informasi video.';
    }
  } catch (error) {
    return `Terjadi kesalahan: ${error.message}`;
  }
}

